export interface TicketDrug {
  productId: string;
  quantity: number;
  price: number;
  name: string;
  ingredients: string[];
}

const ENGLISH_LANG_PREFIX = 'en';

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null;

const toFiniteNumber = (value: unknown): number => {
  const parsed = typeof value === 'string' ? parseFloat(value) : value;

  return typeof parsed === 'number' && Number.isFinite(parsed) ? parsed : 0;
};

const toText = (value: unknown): string => {
  if (typeof value === 'string') {
    return value.trim();
  }

  return typeof value === 'number' && Number.isFinite(value) ? String(value) : '';
};

// Read `{ Name: { Values: [{ Lang, Value }] } }`, preferring the English entry.
const toLocalizedName = (value: unknown): string => {
  const values =
    isRecord(value) && isRecord(value.Name) && Array.isArray(value.Name.Values)
      ? value.Name.Values.filter(isRecord)
      : [];
  const english = values.find((item) =>
    toText(item.Lang).toLowerCase().startsWith(ENGLISH_LANG_PREFIX),
  );

  return (
    toText(english?.Value) ||
    values.map((item) => toText(item.Value)).find(Boolean) ||
    ''
  );
};

// Format one active ingredient as "<name> <amount> <unit>", e.g. "Dabigatran 110 mg".
const toIngredientText = (ingredient: unknown): string => {
  if (!isRecord(ingredient)) {
    return toText(ingredient);
  }

  const name =
    toText(ingredient.ingredient) ||
    toText(ingredient.Ingredient) ||
    toLocalizedName(ingredient.Ingredient);

  return [
    name,
    toText(ingredient.amount ?? ingredient.Amount),
    toText(ingredient.unit ?? ingredient.Unit),
  ]
    .filter(Boolean)
    .join(' ');
};

// Accept ticket drugs (`ingredients`) as well as drug details (`activeIngredients`).
const toIngredients = (lineItem: Record<string, unknown>): string[] => {
  const source = Array.isArray(lineItem.ingredients)
    ? lineItem.ingredients
    : lineItem.activeIngredients;

  return Array.isArray(source)
    ? source.map(toIngredientText).filter(Boolean)
    : [];
};

// Map shopping-cart line items to the `drugs` entries stored in the ticket valueAsJson.
export const buildTicketDrugs = (lineItems: unknown): TicketDrug[] => {
  if (!Array.isArray(lineItems)) {
    return [];
  }

  return lineItems.reduce<TicketDrug[]>((drugs, lineItem: unknown) => {
    if (!isRecord(lineItem)) {
      return drugs;
    }

    const productId = toText(lineItem.productId);
    const quantity = toFiniteNumber(lineItem.quantity);

    if (!productId || quantity <= 0) {
      return drugs;
    }

    const name = toText(lineItem.name) || toText(lineItem.drugName);
    const ingredients = toIngredients(lineItem);
    const existing = drugs.find((drug) => drug.productId === productId);

    if (existing) {
      // The cart stores one line per "add" tap, so repeated products are merged.
      existing.quantity += quantity;
      existing.name = existing.name || name;
      existing.ingredients =
        existing.ingredients.length > 0 ? existing.ingredients : ingredients;
      return drugs;
    }

    drugs.push({
      productId,
      quantity,
      price: toFiniteNumber(lineItem.price),
      name,
      ingredients,
    });
    return drugs;
  }, []);
};

