import {buildTicketDrugs} from '../src/screens/doctor-detail-screen/ticket-drugs';

describe('buildTicketDrugs', () => {
  test('maps cart line items to ticket drugs', () => {
    expect(
      buildTicketDrugs([
        {productId: 'drug-1', quantity: 2, price: 239.2, isSelected: true},
      ]),
    ).toEqual([
      {productId: 'drug-1', quantity: 2, price: 239.2, name: '', ingredients: []},
    ]);
  });

  test('merges repeated lines of the same product', () => {
    expect(
      buildTicketDrugs([
        {productId: 'drug-1', quantity: 1, price: 1664},
        {productId: 'drug-1', quantity: 1, price: 1664},
      ]),
    ).toEqual([
      {productId: 'drug-1', quantity: 2, price: 1664, name: '', ingredients: []},
    ]);
  });

  test('parses a price returned as a string', () => {
    expect(
      buildTicketDrugs([{productId: 'drug-1', quantity: 1, price: '239.2'}]),
    ).toEqual([
      {productId: 'drug-1', quantity: 1, price: 239.2, name: '', ingredients: []},
    ]);
  });

  test('skips lines without a product id or a positive quantity', () => {
    expect(
      buildTicketDrugs([
        {quantity: 1, price: 10},
        {productId: 'drug-2', quantity: 0, price: 10},
      ]),
    ).toEqual([]);
  });

  test('returns an empty list when the cart has no line items', () => {
    expect(buildTicketDrugs(undefined)).toEqual([]);
  });

  test('takes the name and ingredients from the drug detail fields', () => {
    expect(
      buildTicketDrugs([
        {
          productId: 'drug-pradaxa',
          quantity: 1,
          price: 10,
          drugName: 'Pradaxa',
          activeIngredients: [
            {ingredient: 'Dabigatran', amount: '110', unit: 'mg'},
          ],
        },
      ])[0],
    ).toMatchObject({name: 'Pradaxa', ingredients: ['Dabigatran 110 mg']});
  });

  test('reads an ingredient returned with capitalised localized fields', () => {
    expect(
      buildTicketDrugs([
        {
          productId: 'drug-pradaxa',
