import { Linking, Platform } from 'react-native';

export type AppPlatform = 'ios' | 'android';

const LAUNCH_SCHEMES = new Set([
  'hsbcpaymepay',
  'weixin',
  'alipay',
  'alipays',
  'alipayhk',
  'googlewallet',
  'gpay',
]);

export const urlScheme = (url: string): string => {
  const match = /^([a-z][a-z0-9+.-]*):/i.exec(url.trim());
  return match?.[1]?.toLowerCase() ?? '';
};

const intentField = (url: string, name: string): string | undefined =>
  new RegExp(`;${name}=([^;]+)`, 'i').exec(url)?.[1];

const knownIntentUrl = (url: string): boolean => {
  const scheme = intentField(url, 'scheme')?.toLowerCase();
  const packageName = intentField(url, 'package');
  return (
    (scheme !== undefined && LAUNCH_SCHEMES.has(scheme)) ||
    packageName === 'hk.com.hsbc.paymefromhsbc' ||
    packageName === 'com.tencent.mm' ||
    packageName === 'com.eg.android.AlipayGphone' ||
    packageName === 'hk.alipay.wallet' ||
    packageName === 'com.google.android.apps.walletnfcrel'
  );
};

export const isExternalAppUrl = (url?: string | null): boolean => {
  if (typeof url !== 'string' || url.trim() === '') {
    return false;
  }
  const scheme = urlScheme(url);
  if (LAUNCH_SCHEMES.has(scheme)) {
    return true;
  }
  return scheme === 'intent' && knownIntentUrl(url);
};

const iosStoreApp = (id: string, country = 'hk'): string =>
  `itms-apps://apps.apple.com/${country}/app/id${id}`;

const androidStoreApp = (packageName: string): string[] => [
  `market://details?id=${packageName}`,
  `https://play.google.com/store/apps/details?id=${packageName}`,
];

const weChatStoreUrls = (platform: AppPlatform, locale: string): string[] => {
  if (platform === 'android') {
    return androidStoreApp('com.tencent.mm');
  }
  if (locale === 'zh-Hans') {
    return [iosStoreApp('414478124', 'cn')];
  }
  if (locale === 'zh-Hant') {
    return [iosStoreApp('414478124', 'hk')];
  }
  return [iosStoreApp('414478124', 'us')];
};

export const externalAppStoreUrls = (
  url: string,
  platform: AppPlatform,
  locale: string,
): string[] => {
  if (!isExternalAppUrl(url)) {
    return [];
  }
  const scheme = urlScheme(url);
  const resolvedScheme =
    scheme === 'intent'
      ? intentField(url, 'scheme')?.toLowerCase() ?? ''
      : scheme;
  const packageName = scheme === 'intent' ? intentField(url, 'package') : undefined;

  if (packageName && platform === 'android') {
    return androidStoreApp(packageName);
  }
  if (resolvedScheme === 'hsbcpaymepay') {
    return platform === 'ios'
      ? [iosStoreApp('1184264977')]
      : androidStoreApp('hk.com.hsbc.paymefromhsbc');
  }
  if (resolvedScheme === 'weixin') {
    return weChatStoreUrls(platform, locale);
  }
  if (resolvedScheme === 'alipays' || resolvedScheme === 'alipay') {
    return platform === 'ios'
      ? [iosStoreApp('333206289')]
      : androidStoreApp('com.eg.android.AlipayGphone');
  }
  if (resolvedScheme === 'alipayhk') {
    return platform === 'ios'
      ? [iosStoreApp('1137573775')]
      : androidStoreApp('hk.alipay.wallet');
  }
  if (resolvedScheme === 'googlewallet' || resolvedScheme === 'gpay') {
    return platform === 'ios'
      ? [iosStoreApp('911316560')]
      : androidStoreApp('com.google.android.apps.walletnfcrel');
  }
  return [];
};

const currentPlatform = (): AppPlatform =>
  Platform.OS === 'ios' ? 'ios' : 'android';

export const openExternalAppUrl = async (
  url: string,
  platform: AppPlatform = currentPlatform(),
  locale = 'en',
): Promise<void> => {
  if (!isExternalAppUrl(url)) {
    return;
  }
  try {
    await Linking.openURL(url.trim());
    return;
  } catch {
    // The target app is unavailable. Open its store listing instead.
  }

  const storeUrls = externalAppStoreUrls(url, platform, locale);
  for (const storeUrl of storeUrls) {
    try {
      await Linking.openURL(storeUrl);
      return;
    } catch {
      // Try the next store URL.
    }
  }
};

export const shouldLoadWebViewUrl = (
  url: string | undefined,
  locale: string,
): boolean => {
  if (!isExternalAppUrl(url) || !url) {
    return true;
  }
  void openExternalAppUrl(url, currentPlatform(), locale);
  return false;
};

import {
  externalAppStoreUrls,
  isExternalAppUrl,
} from '../src/components/webView-comp/external-app-url';

describe('external app urls', () => {
  it('only treats confirmed app schemes as external launches', () => {
    expect(isExternalAppUrl('https://payment-stg.heals.asia/payment/1')).toBe(false);
    expect(isExternalAppUrl('about:blank')).toBe(false);
    expect(isExternalAppUrl('heals://callback')).toBe(false);
    expect(isExternalAppUrl('tel:85246271672')).toBe(false);
    expect(isExternalAppUrl('unknownpay://checkout')).toBe(false);
    expect(isExternalAppUrl('hsbcpaymepay://secure.payme.hsbc.com.hk/2/code')).toBe(true);
    expect(isExternalAppUrl('weixin://pay')).toBe(true);
    expect(isExternalAppUrl('googlewallet://save')).toBe(true);
  });

  it('uses the platform store when PayMe or WeChat is not installed', () => {
    expect(externalAppStoreUrls('hsbcpaymepay://pay', 'ios', 'en')).toEqual([
      'itms-apps://apps.apple.com/hk/app/id1184264977',
    ]);
    expect(externalAppStoreUrls('hsbcpaymepay://pay', 'android', 'en')).toEqual([
      'market://details?id=hk.com.hsbc.paymefromhsbc',
      'https://play.google.com/store/apps/details?id=hk.com.hsbc.paymefromhsbc',
    ]);
    expect(externalAppStoreUrls('weixin://pay', 'ios', 'zh-Hant')).toEqual([
      'itms-apps://apps.apple.com/hk/app/id414478124',
    ]);
    expect(externalAppStoreUrls('unknownpay://checkout', 'ios', 'en')).toEqual([]);
  });

  it('reads a confirmed Android package from an intent url', () => {
    expect(
      externalAppStoreUrls(
        'intent://pay#Intent;scheme=alipays;package=com.eg.android.AlipayGphone;end',
        'android',
        'en',
      )[0],
    ).toBe('market://details?id=com.eg.android.AlipayGphone');
    expect(
      isExternalAppUrl('intent://pay#Intent;scheme=unknownpay;package=com.example.app;end'),
    ).toBe(false);
  });
});

